import { Alumno } from '../models/alumno.model';
import { Materia } from '../models/materia.model';
import { Carrera } from '../models/carrera.model';
import { PlanEstudio } from '../models/plan-estudio.model';
import { RegistroAcademico } from '../models/registro-academico.model';
import { EstadoAprobada, EstadoDesaprobada, EstadoCursando } from '../models/estado.model';

// ---------------------------------------------------------------------------
// Materias del plan (correlativas como objetos Materia)
// ---------------------------------------------------------------------------

export const IS101 = new Materia('IS-101', 'Análisis Matemático I',     64, [],               1, 'aprobada');
export const IS102 = new Materia('IS-102', 'Programación I',            64, [],               1, 'aprobada');
export const IS103 = new Materia('IS-103', 'Inglés I',                  32, [],               1, 'aprobada');
export const IS201 = new Materia('IS-201', 'Análisis Matemático II',    64, [IS101],          2, 'aprobada');
export const IS202 = new Materia('IS-202', 'Programación II',           64, [IS102],          2, 'aprobada');
export const IS203 = new Materia('IS-203', 'Base de Datos',             64, [IS202],          2, 'aprobada');
export const IS204 = new Materia('IS-204', 'Sistemas y Organizaciones', 48, [],               2, 'desaprobada');
export const IS301 = new Materia('IS-301', 'Arquitectura de Software',  64, [IS203],          3, 'disponible');
export const IS302 = new Materia('IS-302', 'Programación III',          64, [IS202],          3, 'disponible');
export const IS303 = new Materia('IS-303', 'Probabilidad y Estadística',64, [IS201],          3, 'disponible');
export const IS304 = new Materia('IS-304', 'Inglés IV',                 32, [IS103],          3, 'disponible');
export const IS305 = new Materia('IS-305', 'Redes II',                  64, [IS203],          3, 'disponible');
export const IS401 = new Materia('IS-401', 'Ingeniería de Requerimientos', 48, [IS301, IS303, IS204], 4, 'disponible');
export const IS402 = new Materia('IS-402', 'Proyecto Final',            96, [IS301, IS302, IS305, IS401], 4, 'proxima');

export const MOCK_MATERIAS: Materia[] = [
  IS101, IS102, IS103,
  IS201, IS202, IS203, IS204,
  IS301, IS302, IS303, IS304, IS305,
  IS401, IS402,
];

// ---------------------------------------------------------------------------
// Plan de estudio y carrera
// ---------------------------------------------------------------------------

export const MOCK_PLAN = new PlanEstudio('IS-2020', 2020, MOCK_MATERIAS);
export const MOCK_CARRERA = new Carrera('IS', 2020, 'Ingeniería en Sistemas', MOCK_PLAN);

// ---------------------------------------------------------------------------
// Registros académicos con IEstado
// ---------------------------------------------------------------------------

const registros: RegistroAcademico[] = [
  new RegistroAcademico(IS101, '1C2023', 9, new EstadoAprobada()),
  new RegistroAcademico(IS102, '1C2023', 8, new EstadoAprobada()),
  new RegistroAcademico(IS103, '1C2023', 7, new EstadoAprobada()),
  new RegistroAcademico(IS201, '2C2023', 8, new EstadoAprobada()),
  new RegistroAcademico(IS202, '2C2023', 9, new EstadoAprobada()),
  new RegistroAcademico(IS203, '1C2024', 8, new EstadoAprobada()),
  new RegistroAcademico(IS204, '1C2024', 3, new EstadoDesaprobada()),
  new RegistroAcademico(IS301, '2C2024', 0, new EstadoCursando()),
];

// ---------------------------------------------------------------------------
// Alumno mock
// ---------------------------------------------------------------------------

export const MOCK_ALUMNO = new Alumno('123456', 'Juan Pérez', 7.9, MOCK_CARRERA, registros);
